SELECT table_name,column_name FROM information_schema.columns WHERE table_schema=DATABASE() AND ((table_name='trade_signal' AND column_name='data_quality_valid') OR (table_name='trade_signal_test' AND column_name IN ('btc_context_candle_close_time','btc_context_age_seconds','btc_context_freshness_threshold_seconds','signal_mode','data_quality_valid')) OR table_name='buy_htf_assessment_audit') ORDER BY table_name,ordinal_position